import type { ProductEntry } from "../../../apps/portal-web/src/registry.ts";

/** Renders PROJECT_INDEX.md from the registry. Pure: same input → byte-identical output. */
export function renderIndex(products: readonly ProductEntry[]): string {
  const header = [
    "# PROJECT_INDEX",
    "",
    "<!-- GENERATED by `just index` from apps/portal-web/src/registry.ts — do not edit by hand. -->",
    "",
    `Products: ${products.length}.`,
    "",
    "| ID | Product | Slug | Profile | Status | Wave | Directory |",
    "|---|---|---|---|---|---|---|",
  ];
  const rows = products.map((p) => {
    const dir = `products/${p.id.toLowerCase()}-${p.slug}`;
    return `| ${p.id} | ${p.title} | ${p.slug} | ${p.profiles.join("+")} | ${p.status} | ${p.wave ?? "—"} | \`${dir}\` |`;
  });
  const counts = new Map<string, number>();
  for (const p of products) counts.set(p.status, (counts.get(p.status) ?? 0) + 1);
  const summary = [...counts.entries()].map(([s, n]) => `${s}: ${n}`).join(", ");
  return [...header, ...rows, "", `Status summary: ${summary}.`, ""].join("\n");
}
